from __future__ import annotations

import html
import json
from datetime import datetime, timezone
from pathlib import Path


def render_dashboard(payload: dict) -> str:
    scenes = payload["scenes"]
    total = sum(scene["duration_sec"] for scene in scenes)
    rows = []
    for scene in scenes:
        rows.append(
            "<tr>"
            f"<td>{scene['id']}</td>"
            f"<td>{scene['start_sec']:.3f}</td>"
            f"<td>{scene['duration_sec']:.3f}</td>"
            f"<td>{html.escape(scene['text'])}</td>"
            f"<td>{html.escape(scene['source'])}</td>"
            "</tr>"
        )
    return f"""<!doctype html>
<html lang="ru"><meta charset="utf-8"><title>Video Assembler Dashboard</title>
<style>body{{font:15px system-ui;margin:32px;background:#111;color:#eee}}table{{border-collapse:collapse;width:100%}}th,td{{padding:9px;border-bottom:1px solid #333;text-align:left;vertical-align:top}}th{{color:#9ad}}.meta{{margin:12px 0 24px;color:#aaa}}</style>
<h1>Тестовый дашборд раскадровки</h1>
<div class="meta">Канал: {html.escape(payload['channel'])} · Сцен: {len(scenes)} · Длительность: {total:.3f} с</div>
<table><thead><tr><th>ID</th><th>Начало</th><th>Длительность</th><th>Текст</th><th>Источник</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></html>"""


def render_review(payload: dict) -> str:
    data = json.dumps(payload, ensure_ascii=False).replace("</", "<\\/")
    return f"""<!doctype html>
<html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Предпросмотр — Video Assembler</title>
<style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#0e0f12;color:#e7e7ea;font:14px/1.5 system-ui,sans-serif}}
header{{position:sticky;top:0;z-index:10;background:#15161aeF;border-bottom:1px solid #2a2c33;padding:11px 20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;backdrop-filter:blur(8px)}}
h1{{font-size:15px;margin:0}}.sub{{color:#9a9aa2;font-size:13px}}.spacer{{flex:1}}button,.upload{{background:#2b2d36;color:#e7e7ea;border:1px solid #3a3d48;border-radius:7px;padding:7px 11px;font:inherit;cursor:pointer}}button:hover,.upload:hover{{background:#343742}}
#count{{font-weight:700}}#need{{background:#f59e0b;color:#1a1400;border-color:#f59e0b;font-weight:700}}#grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:16px;padding:20px;max-width:1640px;margin:auto}}
.card{{background:#17181d;border:1px solid #262830;border-radius:12px;overflow:hidden}}.card.marked{{border-color:#e04a3a;box-shadow:0 0 0 2px #e04a3a55}}.thumb{{position:relative;aspect-ratio:16/9;background:#0b0b0d;display:flex;align-items:center;justify-content:center;color:#6b6b73}}.thumb img{{width:100%;height:100%;object-fit:cover;display:block}}.num{{position:absolute;left:8px;top:8px;background:#000b;padding:2px 8px;border-radius:6px;font-weight:700}}.badge{{position:absolute;right:8px;top:8px;background:#16a34a;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700}}figcaption{{padding:10px 13px 13px}}.meta{{color:#8b8b93;font-size:12px}}.query{{color:#7f8ea3;font-size:12px;margin:4px 0;word-break:break-word}}.txt{{margin:0;color:#d7d7db}}.acts{{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}}.acts button{{font-size:12px;padding:6px 9px}}.acts .on{{background:#e04a3a;border-color:#e04a3a}}.acts .keep{{background:#1f5133;border-color:#2f7a4c}}.acts .ban{{background:#5c1f22;border-color:#8c2f34}}.upload{{display:inline-block}}input[type=file]{{display:none}}textarea{{display:none;width:100%;min-height:54px;margin-top:9px;background:#0e0f12;color:#e7e7ea;border:1px solid #3a3d48;border-radius:7px;padding:7px;font:inherit;resize:vertical}}.marked textarea{{display:block}}.need{{display:none;background:#f59e0b;color:#1a1400;font-weight:800;text-align:center;padding:5px;font-size:12px}}.card.needup .need{{display:block}}
.opts{{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}}.opt{{position:relative;width:92px;height:62px;padding:0;overflow:hidden;border-radius:6px;background:#0b0b0d;border:2px solid transparent}}.opt:hover{{border-color:#46d39a}}.opt img{{width:100%;height:100%;object-fit:cover;display:block}}.opt span{{position:absolute;left:2px;right:2px;bottom:2px;background:#000b;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
.overlay{{margin-top:10px;padding:9px;border:1px solid #6a4d8c;border-radius:8px;background:#1e1830}}.overlay input,.overlay select{{background:#0e0f12;color:#e7e7ea;border:1px solid #3a3d48;border-radius:5px;padding:5px;width:82px;margin:2px}}.overlay input[type=text]{{width:100%}}.overlay button{{font-size:11px;padding:5px 8px;margin:3px 2px 0 0}}.overlay .ok{{background:#1f6b4f;border-color:#2f8f6a}}.overlay .clear{{background:#5c1f22;border-color:#8c2f34}}
.overlay .photo{{display:inline-block;background:#243b5e;border:1px solid #3a5a8c;padding:5px 8px;border-radius:5px;font-size:11px}}
.thumb video{{width:100%;height:100%;object-fit:cover;display:block}}
</style><body><header><h1>Предпросмотр видеоряда</h1><span class="sub" id="summary"></span><span class="spacer"></span><span class="sub">отмечено: <b id="count">0</b></span><button id="need">⚠️ нужно твоё фото: 0</button><button id="export">📋 Показать правки</button><button id="approve">✅ Утвердить ролик</button><button id="reset">Сбросить</button></header><main id="grid"></main>
<script>
const payload={data}; const state=JSON.parse(localStorage.getItem('video-assembler-review')||'{{}}');
const grid=document.querySelector('#grid'); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function card(s){{const x=state[s.id]||{{}};const opts=(x.options||[]).map((o,i)=>`<button class="opt" data-a="pick" data-index="${{i}}">${{o.thumb?`<img src="${{esc(o.thumb)}}">`:`<span class="webopt">${{esc(o.title||o.full||'веб-страница')}}</span>`}}<span>${{esc(o.src||o.kind||'')}}</span></button>`).join('');return `<figure class="card ${{x.mark?'marked ':''}}${{x.need?'needup':''}}" data-id="${{s.id}}"><div class="thumb">${{x.image?`<img src="${{x.image}}">`:'кадр ещё не найден'}}<span class="num">${{s.id}}</span><span class="badge">${{esc(s.source)}}</span></div><div class="need">⚠️ НУЖНО ТВОЁ ФОТО</div><figcaption><div class="meta">СЦЕНА ${{String(s.id).padStart(2,'0')}} · ${{s.start_sec.toFixed(1)}} с · ${{s.duration_sec.toFixed(1)}} с</div><div class="query">${{esc(s.source_query)}}</div><p class="txt">${{esc(s.text)}}</p><div class="acts"><button data-a="edit">✏️ Изменить кадр</button><button data-a="search">🔍 Искать</button><label class="upload">⬆️ Загрузить<input type="file" accept="image/*" data-a="upload"></label><button class="keep" data-a="keep">✓ Оставить</button><button class="ban" data-a="ban">✕ Забраковать</button></div><div class="opts">${{opts}}</div><div class="overlay"><b>ВСПЛЫВАШКА</b><input type="text" data-f="words" placeholder="Текст всплывашки"><input type="number" step="0.01" data-f="at" value="0.35"><input type="number" step="0.1" data-f="scale" value="1"><select data-f="shape"><option>rect</option><option>rounded</option><option>square</option><option>circle</option></select><select data-f="sound"><option>pop</option><option>whoosh</option><option>ding</option><option>pshik</option></select><button data-a="overlay-save">Сохранить</button><button class="ok" data-a="overlay-approve">✓ Подтвердить</button><button class="clear" data-a="overlay-clear">✕ Очистить</button></div><textarea placeholder="Что изменить или почему забраковано?">${{esc(x.note||'')}}</textarea></figcaption></figure>`}}
function installOverlayUploads(){{document.querySelectorAll('.overlay').forEach(p=>{{if(p.querySelector('[data-a=overlay-upload]'))return;const label=document.createElement('label');label.className='photo';label.textContent='⬆️ Фото';const input=document.createElement('input');input.type='file';input.accept='image/*';input.dataset.a='overlay-upload';label.appendChild(input);p.prepend(label);const row=document.createElement('div');row.innerHTML='<select data-f="color"><option>white</option><option>yellow</option><option>red</option><option>green</option><option>orange</option></select><select data-f="font"><option>default</option><option>arial</option><option>times</option><option>oswald</option><option>montserrat</option><option>roboto</option></select><select data-f="textpos"><option value="tl">↖</option><option value="tc">↑</option><option value="tr">↗</option><option value="ml">←</option><option value="mc">·</option><option value="mr">→</option><option value="bl" disabled>↙</option><option value="bc" disabled>↓</option><option value="br" disabled>↘</option></select><button data-a="overlay-text-save">Сохранить текст</button><input type="text" data-f="ticker" placeholder="Ticker"><button data-a="ticker-save">Сохранить ticker</button>';p.appendChild(row)}})}}
function installVideoPreviews(){{document.querySelectorAll('.card').forEach(c=>{{const x=state[c.dataset.id];if(!x?.video)return;const thumb=c.querySelector('.thumb');thumb.innerHTML=`<video controls muted preload="metadata" src="${{esc(x.video)}}"></video><span class="num">${{c.dataset.id}}</span>`}})}}
function render(){{grid.innerHTML=payload.scenes.map(card).join('');installOverlayUploads();installVideoPreviews();document.querySelector('#summary').textContent=`${{payload.scenes.length}} сцен · ${{payload.scenes.reduce((a,s)=>a+s.duration_sec,0).toFixed(1)}} с`;const vals=Object.values(state);document.querySelector('#count').textContent=vals.filter(x=>x.mark||x.need).length;document.querySelector('#need').textContent=`⚠️ нужно твоё фото: ${{vals.filter(x=>x.need).length}}`}}
function save(){{localStorage.setItem('video-assembler-review',JSON.stringify(state));render()}}
async function api(path,options={{}}){{const r=await fetch(path,options);if(!r.ok)throw new Error(await r.text());return r.json()}}
async function refreshState(){{try{{const live=await api('/state?_probe=1');state._overlays=live.overlays||{{}};for(const s of live.scenes){{state[s.id]=state[s.id]||{{}};if(s.thumb)state[s.id].image='/'+s.thumb;if(s.video)state[s.id].video='/'+s.video;if(s.status==='failed')state[s.id].need=true}}render()}}catch(e){{}}}}
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a^="overlay-"]');if(!b||b.dataset.a==='overlay-text-save')return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');try{{if(b.dataset.a==='overlay-clear'){{await api('/overlay?id='+id+'&clear=1',{{method:'POST'}})}}else{{const body={{sound:p.querySelector('[data-f=sound]').value,at:Number(p.querySelector('[data-f=at]').value),shape:p.querySelector('[data-f=shape]').value,scale:Number(p.querySelector('[data-f=scale]').value),approved:b.dataset.a==='overlay-approve',text:{{words:p.querySelector('[data-f=words]').value,at:Number(p.querySelector('[data-f=at]').value),scale:Number(p.querySelector('[data-f=scale]').value),sound:p.querySelector('[data-f=sound]').value}}}};await api('/overlay?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}})}}await refreshState()}}catch(err){{alert('Ошибка overlay API: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a="overlay-text-save"]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');const pos=p.querySelector('[data-f=textpos]').value;if(pos.startsWith('b')){{alert('Нижняя строка запрещена: там будут субтитры');return}}try{{await api('/overlay_text?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{words:p.querySelector('[data-f=words]').value,color:p.querySelector('[data-f=color]').value,font:p.querySelector('[data-f=font]').value,pos,at:Number(p.querySelector('[data-f=at]').value),scale:Number(p.querySelector('[data-f=scale]').value),sound:p.querySelector('[data-f=sound]').value}})}});await refreshState()}}catch(err){{alert('Ошибка текста overlay: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a="ticker-save"]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');try{{await api('/ticker?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{words:p.querySelector('[data-f=ticker]').value,at:Number(p.querySelector('[data-f=at]').value),sound:p.querySelector('[data-f=sound]').value}})}});await refreshState()}}catch(err){{alert('Ошибка ticker API: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('button');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,x=state[id]||{{}};try{{if(b.dataset.a==='edit'||b.dataset.a==='search'){{x.mark=true;x.note=b.dataset.a==='edit'?'Изменить кадр: ':'Искать в интернете: ';const q=x.note;const result=await api('/search_opts?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{q:q}})}});x.options=result.options||[];if(!x.options.length&&result.errors?.length)x.note+=' Нет ответа: '+result.errors.map(v=>v.source).join(', ')}}if(b.dataset.a==='pick'){{const option=x.options[Number(b.dataset.index)];const result=await api('/pick_opt?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...option,target:'scene'}})}});x.image='/'+result.path;x.options=[];x.mark=true;x.need=false}}if(b.dataset.a==='keep'){{x.mark=false;x.need=false;await api('/keepimg?id='+id,{{method:'POST'}})}}if(b.dataset.a==='ban'){{x.mark=true;x.need=true;await api('/ban_asset?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{}})}})}}state[id]=x;save()}}catch(err){{x.note='Ошибка API: '+err.message;state[id]=x;save()}}}});
grid.addEventListener('input',e=>{{if(e.target.tagName==='TEXTAREA'){{const id=e.target.closest('.card').dataset.id;state[id]=state[id]||{{}};state[id].note=e.target.value;localStorage.setItem('video-assembler-review',JSON.stringify(state))}}}});
grid.addEventListener('change',async e=>{{if(e.target.dataset.a!=='upload')return;const f=e.target.files[0];if(!f)return;const id=e.target.closest('.card').dataset.id;try{{await fetch('/upload?id='+id,{{method:'POST',headers:{{'X-Filename':encodeURIComponent(f.name),'Content-Type':f.type||'application/octet-stream'}},body:await f.arrayBuffer()}});state[id]=state[id]||{{}};state[id].image=URL.createObjectURL(f);state[id].mark=true;state[id].need=false;save()}}catch(err){{alert('Ошибка загрузки: '+err.message)}}}});
grid.addEventListener('change',async e=>{{if(e.target.dataset.a!=='overlay-upload')return;const f=e.target.files[0];if(!f)return;const id=e.target.closest('.card').dataset.id;try{{await fetch('/overlay_photo?id='+id,{{method:'POST',headers:{{'X-Filename':encodeURIComponent(f.name),'Content-Type':f.type||'application/octet-stream'}},body:await f.arrayBuffer()}});await refreshState()}}catch(err){{alert('Ошибка загрузки фото-всплывашки: '+err.message)}}}});
document.querySelector('#reset').onclick=()=>{{localStorage.removeItem('video-assembler-review');Object.keys(state).forEach(k=>delete state[k]);render()}};document.querySelector('#export').onclick=()=>{{const out=payload.scenes.map(s=>{{const x=state[s.id];return x&&(x.mark||x.need)?`Сцена ${{s.id}}: ${{x.note||'нужна правка'}}`:''}}).filter(Boolean).join('\\n');alert(out||'Правок пока нет')}};
document.querySelector('#approve').onclick=async()=>{{if(Object.values(state).some(x=>x.need)){{alert('Сначала закройте жёлтые карточки');return}};try{{await api('/approve',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{approved:true}})}});alert('Ролик утверждён для render')}}catch(e){{alert('Ошибка утверждения: '+e.message)}}}};render();refreshState();setInterval(refreshState,2500);
</script></body></html>"""


def write_outputs(payload: dict, output_dir: Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / "scenes.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (output_dir / "dashboard.html").write_text(render_dashboard(payload), encoding="utf-8")
    (output_dir / "review.html").write_text(render_review(payload), encoding="utf-8")
    manifest = {
        "status": "dashboard_ready",
        "scene_count": len(payload["scenes"]),
        "duration_sec": round(sum(scene["duration_sec"] for scene in payload["scenes"]), 3),
        "outputs": ["scenes.json", "dashboard.html", "review.html", "manifest.json"],
        "generated_at": datetime.now(timezone.utc).isoformat(),
    }
    (output_dir / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
